const mk=(r)=>`=INDEX(RateHurdles!$E$2:$E$17,MATCH(1,INDEX((RateHurdles!$D$2:$D$17=$C${r})*(RateHurdles!$C$2:$C$17=$B${r})*(RateHurdles!$A$2:$A$17<=$D${r})*(RateHurdles!$B$2:$B$17>=$D${r}),0),0))`;
for(const r of [2,3]) wb.getRange('Deposits!A'+r).setValue(mk(r));
const chk1=wb.evaluate(`=SUMPRODUCT((RateHurdles!$D$2:$D$17=Deposits!C2)*(RateHurdles!$C$2:$C$17=Deposits!B2)*(RateHurdles!$A$2:$A$17<=Deposits!D2)*(RateHurdles!$B$2:$B$17>=Deposits!D2))`);
const chk2=wb.evaluate(`=SUMPRODUCT((RateHurdles!$D$2:$D$17=Deposits!C3)*(RateHurdles!$C$2:$C$17=Deposits!B3)*(RateHurdles!$A$2:$A$17<=Deposits!D3)*(RateHurdles!$B$2:$B$17>=Deposits!D3)*RateHurdles!$E$2:$E$17)`);
log('row2 match count',chk1,'row3 rate check',chk2);
const a=wb.getRange('Deposits!A2:A3');
log(a);
[a.getValues(), wb.getRange('Deposits!A2').getCell().getFormula?.(), wb.getRange('Deposits!A2').getStyle().getNumberFormat?.(), wb.getRange('Deposits!A3').getStyle().getNumberFormat?.()].map(x=>JSON.stringify(x)).join(' | ')

